<?php

namespace Tests\Feature;

use App\Support\CompanyConnectionFactory;
use App\Support\CmtAuth;
use Illuminate\Support\Str;
use Symfony\Component\HttpFoundation\Cookie;
use Tests\TestCase;

/**
 * Cross-app primitive vectors — the anti-circular suite.
 *
 * Every expected value comes from tests/Fixtures/parity_vectors.json,
 * GENERATED BY EXECUTING THE REAL PYTHON STACK (tools/gen_parity_vectors.py:
 * app.auth, FastAPI validation, Starlette cookies). PHP never derives an
 * expected value from itself; it only produces its own output and asserts
 * equality with the recorded Python output.
 *
 * Regenerate the fixture after any change to the Python reference:
 *     python tools/gen_parity_vectors.py
 * (CI-style staleness check: python tools/gen_parity_vectors.py --check)
 */
class CrossAppVectorsTest extends TestCase
{
    private static array $vectors;

    public static function setUpBeforeClass(): void
    {
        $file = __DIR__.'/../Fixtures/parity_vectors.json';
        self::$vectors = json_decode((string) file_get_contents($file), true, 512, JSON_THROW_ON_ERROR);
    }

    protected function setUp(): void
    {
        parent::setUp();

        // Isolated data dir so nothing here touches the shared repo data/.
        $dir = storage_path('framework/testing/'.Str::random(10));
        if (! is_dir($dir)) {
            mkdir($dir, 0777, true);
        }
        config(['cmt.data_dir' => $dir, 'cmt.users_env' => '']);
        touch($dir.'/CMT.db');
    }

    private function auth(): CmtAuth
    {
        return $this->app->make(CmtAuth::class);
    }

    /** Parse a Set-Cookie header into [lowercased attr => value|true]. */
    private static function attrs(string $header): array
    {
        $out = [];
        foreach (explode(';', $header) as $i => $part) {
            $part = trim($part);
            if ($i === 0) {
                [$out['__name__'], $out['__value__']] = array_pad(explode('=', $part, 2), 2, null);

                continue;
            }
            $kv = array_pad(explode('=', $part, 2), 2, null);
            $out[strtolower(trim($kv[0]))] = $kv[1] !== null ? trim($kv[1]) : true;
        }

        // Starlette quotes an empty value (cmt_session=""); Symfony prints it
        // bare (cmt_session=). Same semantics — normalize before comparing.
        if ($out['__value__'] === '""') {
            $out['__value__'] = '';
        }

        return $out;
    }

    /** Assert two Set-Cookie headers expose the SAME attribute set + values (order-insensitive). */
    private static function assertSameCookieShape(string $phpHeader, string $pyHeader, string $which): void
    {
        $php = self::attrs($phpHeader);
        $py = self::attrs($pyHeader);

        self::assertSame($py['__name__'], $php['__name__'], "$which: cookie name");
        self::assertSame($py['__value__'], $php['__value__'], "$which: cookie value");

        unset($py['__name__'], $py['__value__'], $php['__name__'], $php['__value__']);
        ksort($py);
        ksort($php);
        self::assertSame(
            array_keys($py),
            array_keys($php),
            "$which: Set-Cookie attribute set differs (Python = ".implode(',', array_keys($py)).' / PHP = '.implode(',', array_keys($php)).')'
        );
        foreach ($py as $attr => $val) {
            if ($val !== true) {
                self::assertSame($val, $php[$attr], "$which: attribute {$attr}");
            }
        }
    }

    /** Same as above, but tolerates listed PHP-only attributes (platform noise). */
    private static function assertSameCookieShapeAfterIgnoring(
        string $phpHeader,
        string $pyHeader,
        array $ignorePhpAttrs,
        string $which,
    ): void {
        $php = self::attrs($phpHeader);
        $py = self::attrs($pyHeader);

        foreach ($ignorePhpAttrs as $attr) {
            unset($php[strtolower($attr)]);
        }
        unset($py['__name__'], $py['__value__'], $php['__name__'], $php['__value__']);
        ksort($py);
        ksort($php);

        self::assertSame(
            array_keys($py),
            array_keys($php),
            "$which: attribute set (ignoring PHP-only: ".implode(',', $ignorePhpAttrs).')'
        );
        foreach ($py as $attr => $val) {
            if ($val !== true) {
                self::assertSame($val, $php[$attr], "$which: attribute {$attr}");
            }
        }
    }

    // ── Constants ─────────────────────────────────────────────────────────

    public function test_role_levels_match_python(): void
    {
        $this->assertSame(
            self::$vectors['constants']['role_levels'],
            CmtAuth::ROLE_LEVEL,
            'role hierarchy must be byte-identical (same order => same tie-breaking)'
        );
    }

    public function test_session_ttl_matches_python(): void
    {
        $this->assertEquals(
            self::$vectors['constants']['session_ttl_hours'],
            config('cmt.session_ttl_hours'),
            'session TTL hours must match Python SESSION_TTL (8h)'
        );
    }

    // ── PBKDF2 (the credential-compat linchpin) ───────────────────────────

    public function test_pbkdf2_hashes_equal_python_output(): void
    {
        $this->assertSame(200000, self::$vectors['constants']['pbkdf2_iterations']);

        foreach (self::$vectors['pbkdf2'] as $case) {
            // The fixture records the EXACT bytes Python hashed (UTF-8).
            // PHP strings are byte sequences, so equality here proves hashPw
            // consumes the same input bytes before the KDF.
            $this->assertSame(
                $case['pw_bytes_hex'],
                bin2hex($case['pw']),
                "{$case['id']}: fixture pw must be the byte-exact input"
            );
            $this->assertSame(
                $case['expected_hash'],
                CmtAuth::hashPw($case['pw'], $case['salt']),
                "{$case['id']}: PHP hash must equal Python pbkdf2_hmac(sha256, pw, salt, 200000, dklen=32).hex()"
            );
        }
    }

    // ── Session tokens ────────────────────────────────────────────────────

    public function test_session_tokens_match_python_token_urlsafe_32_shape(): void
    {
        $spec = self::$vectors['tokens']['urlsafe32'];
        $method = new \ReflectionMethod(CmtAuth::class, 'token');
        $method->setAccessible(true);
        $auth = new CmtAuth($this->app->make(CompanyConnectionFactory::class));

        for ($i = 0; $i < 50; $i++) {
            $token = $method->invoke($auth);
            $this->assertSame($spec['length'], strlen($token));
            $this->assertSame(1, preg_match('/'.$spec['php_regex'].'/', $token));
        }
    }

    // ── Timestamps ────────────────────────────────────────────────────────

    public function test_isoformat_rendering_matches_python(): void
    {
        foreach (self::$vectors['timestamps']['iso_vectors'] as $vector) {
            $php = (new \DateTimeImmutable($vector['utc_iso'], new \DateTimeZone('UTC')))
                ->format('Y-m-d\TH:i:s.uP');

            if (isset($vector['note']) && str_contains($vector['note'], "omits '.000000'")) {
                // KNOWN DIVERGENCE (documented in the fixture): Python drops
                // the fraction when microsecond == 0; PHP's .u always prints 6
                // digits. The PHP rendering must equal Python's with the
                // fraction inserted before the UTC offset.
                $this->assertSame(
                    str_replace('+00:00', '.000000+00:00', $vector['expected']),
                    $php,
                    $vector['id']
                );

                continue;
            }

            $this->assertSame($vector['expected'], $php, $vector['id']);
        }
    }

    public function test_iso_now_matches_python_shape(): void
    {
        $this->assertSame(
            1,
            preg_match('/'.self::$vectors['timestamps']['isoformat_shape_regex'].'/', CmtAuth::isoNow()),
            'CmtAuth::isoNow() must render Python datetime.isoformat() shape'
        );
    }

    public function test_sqlite_datetime_default_matches_python(): void
    {
        // Both apps create users/sessions with SQLite's DEFAULT (datetime('now'))
        // — same DDL, so the storage format must satisfy the same regex.
        $conn = $this->app->make(CompanyConnectionFactory::class)->authConnection();
        $conn->statement('CREATE TABLE IF NOT EXISTS _vec_t (id INTEGER PRIMARY KEY, created_at TEXT NOT NULL DEFAULT (datetime(\'now\')))');
        $conn->statement('INSERT INTO _vec_t (id) VALUES (1)');
        $stored = $conn->table('_vec_t')->where('id', 1)->value('created_at');
        $conn->statement('DROP TABLE _vec_t');

        $this->assertSame(
            1,
            preg_match('/'.self::$vectors['timestamps']['sqlite_datetime_now_regex'].'/', (string) $stored),
            "SQLite datetime('now') default must render the Python-shared shape, got: ".var_export($stored, true)
        );
    }

    // ── str.capitalize (seeder display_name) ─────────────────────────────

    public function test_capitalize_matches_python(): void
    {
        foreach (self::$vectors['capitalize'] as $vector) {
            $this->assertSame(
                $vector['expected'],
                CmtAuth::capitalize($vector['input']),
                'capitalize('.var_export($vector['input'], true).')'
            );
        }
    }

    // ── JSON encoding (API responses) ─────────────────────────────────────

    public function test_json_encoding_matches_fastapi_jsonresponse(): void
    {
        foreach (self::$vectors['json_dumps'] as $vector) {
            $flags = JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE;

            if (isset($vector['note']) && str_contains($vector['note'], 'int-valued float')) {
                // KNOWN DIVERGENCE (unfixable in PHP json_encode semantics):
                // Python emits int-valued floats as "1.0"; PHP prints "1".
                // Pinned so it can never become a silent mismatch: the
                // spellings differ, the decoded VALUE must be identical.
                $php = json_encode($vector['obj'], $flags);
                $this->assertNotSame($vector['expected'], $php, $vector['id']);
                $this->assertEquals(
                    json_decode($vector['expected']),
                    json_decode($php),
                    $vector['id'].': decoded value must survive the spelling divergence'
                );

                continue;
            }

            if (isset($vector['note']) && str_contains($vector['note'], 'exponent spelling')) {
                // Known divergence: Python prints 1e+20, PHP prints 1.0e+20
                // (exponent spelling only; the VALUE is identical). The P5
                // capture normalizer rounds floats to 4dp, so this cannot
                // surface as a parity diff. Pinned as a known equivalence.
                $php = json_encode($vector['obj'], $flags);
                $this->assertNotSame($vector['expected'], $php, $vector['id']);
                $this->assertEquals(
                    json_decode($vector['expected']),
                    json_decode($php),
                    $vector['id'].': numeric value must survive despite exponent spelling'
                );

                continue;
            }

            $php = json_encode($vector['obj'], $flags | JSON_THROW_ON_ERROR);

            $this->assertSame($vector['expected'], $php, $vector['id']);
        }
    }

    // ── Cookies ───────────────────────────────────────────────────────────

    public function test_set_cookie_headers_match_starlette(): void
    {
        foreach (self::$vectors['cookies'] as $vector) {
            if ($vector['kind'] !== 'set' || $vector['name'] !== 'cmt_session') {
                continue; // session vectors compared byte-shape-exact below
            }

            $secure = str_contains($vector['python_header'], 'Secure');
            // expire = 0 -> no Max-Age/Expires (browser-session cookie).
            $php = (string) Cookie::create(
                $vector['name'],
                $vector['value'],
                0,
                '/',
                null,
                $secure,
                true, // HttpOnly — Python's cmt_session always carries it
                false,
                'lax',
            );

            $this->assertSameCookieShape($php, $vector['python_header'], $vector['id']);
        }
    }

    public function test_db_cookie_is_not_httponly_like_python(): void
    {
        // Explicit pin of the KG-level nuance: Python's cmt_db has NO HttpOnly.
        $vector = collect(self::$vectors['cookies'])->firstWhere('id', 'db_cookie_set');

        // Built the way SetDbController builds it: the cookie() helper takes
        // MINUTES and converts to an absolute expiry (Max-Age ≈ 31536000 s).
        $php = (string) cookie('cmt_db', 'CME', 60 * 24 * 365, '/', null, false, false, false, 'lax');
        $phpAttrs = self::attrs($php);
        $pyAttrs = self::attrs($vector['python_header']);

        $this->assertArrayNotHasKey('httponly', $phpAttrs, 'cmt_db must NOT be HttpOnly (Python parity)');
        $this->assertArrayNotHasKey('httponly', $pyAttrs);
        $this->assertSame($pyAttrs['__name__'], $phpAttrs['__name__']);
        $this->assertSame($pyAttrs['__value__'], $phpAttrs['__value__']);
        $this->assertSame($pyAttrs['path'], $phpAttrs['path']);
        $this->assertSame($pyAttrs['samesite'], $phpAttrs['samesite']);
        $this->assertArrayHasKey('max-age', $phpAttrs);
        // Symfony ALWAYS pairs Expires with Max-Age; Starlette emits Max-Age
        // only. Same lifetime semantics, one extra harmless attribute —
        // recorded here as a known, deliberate platform difference.
        $this->assertArrayNotHasKey('expires', $pyAttrs);
        $this->assertArrayHasKey('expires', $phpAttrs);
        // One-year Max-Age (±10 s of clock skew between set and render).
        $this->assertEqualsWithDelta(
            (int) $pyAttrs['max-age'],
            (int) $phpAttrs['max-age'],
            10,
            'cmt_db Max-Age must be one year (Python max_age=31536000)'
        );
    }

    public function test_session_cookie_has_no_max_age_like_python(): void
    {
        // Explicit pin: Python's cmt_session is a browser-session cookie (no
        // Max-Age/Expires); PHP reproduces this with expire = 0.
        $vector = collect(self::$vectors['cookies'])->firstWhere('id', 'session_cookie_set');
        $php = (string) cookie('cmt_session', 'tok', 0, '/', null, false, true, false, 'lax');

        $this->assertStringNotContainsStringIgnoringCase('max-age', $php);
        $this->assertStringNotContainsStringIgnoringCase('max-age', $vector['python_header']);
        $this->assertStringNotContainsStringIgnoringCase('expires', $php);
        $this->assertStringNotContainsStringIgnoringCase('expires', $vector['python_header']);
        $this->assertSameCookieShape($php, $vector['python_header'], 'session_cookie_set');
    }

    public function test_delete_cookie_deletes_like_starlette(): void
    {
        // Byte equality is impossible (both sides embed a wall-clock expiry
        // date); the CONTRACT is: empty value + expired attribute set, so the
        // browser removes the cookie on either app.
        $vector = collect(self::$vectors['cookies'])->firstWhere('id', 'db_cookie_delete');

        // Starlette quotes the empty value (cmt_session=""); semantics are
        // what matter: deletion value + Max-Age=0 + expired.
        $this->assertSame('', self::attrs($vector['python_header'])['__value__']);
        $this->assertStringContainsString('Max-Age=0', $vector['python_header']);

        $php = (string) cookie()->forget('cmt_session');
        $phpAttrs = self::attrs($php);

        // Laravel's forget sends the 'deleted' sentinel (Starlette sends "")
        // — different spelling, same browser instruction: drop the cookie.
        $this->assertContains(
            $phpAttrs['__value__'],
            ['', 'deleted'],
            'PHP forget must carry a deletion value'
        );
        $this->assertArrayHasKey('expires', $phpAttrs, 'PHP forget must set an expiry');
        $this->assertTrue(
            isset($phpAttrs['max-age']) && (int) $phpAttrs['max-age'] <= 0,
            'PHP forget Max-Age must be <= 0, got: '.var_export($phpAttrs['max-age'] ?? null, true)
        );
        $this->assertStringContainsString('expires=<EXPIRES>', $vector['python_header']);
    }

    // ── FastAPI validation shape (missing login fields) ──────────────────

    public function test_missing_login_fields_return_fastapi_422_shape(): void
    {
        $expected = self::$vectors['validation_422'];

        $response = $this->post('/login', []);

        $this->assertSame($expected['status'], $response->status(), 'missing fields must 422 like FastAPI');
        $this->assertSame($expected['body'], $response->json(), 'body must mirror FastAPI field order, msg, and shape');
    }

    public function test_partial_login_fields_return_fastapi_422_for_missing_one(): void
    {
        $expected = self::$vectors['validation_422'];
        $expectedBody = ['detail' => [$expected['body']['detail'][1]]];

        $response = $this->post('/login', ['username' => 'admin']);

        $this->assertSame(422, $response->status());
        $this->assertSame($expectedBody, $response->json(), 'single missing field must render exactly like FastAPI');
    }
}
